{
  "type": "notes",
  "metadata": {
    "estimatedReadingMinutes": 4
  },
  "summary": "An Operating System (OS) serves as an intermediary between hardware and users, managing resources like the CPU, memory, and I/O devices. Key functions include process management (scheduling and multitasking), memory management (allocation and protection), file system organization, and I/O management via drivers. The OS must also handle complex challenges like deadlocks, where processes wait indefinitely for resources, and synchronization, which ensures safe access to shared data through mechanisms like semaphores and mutexes.",
  "keyConcepts": [
    "Process Management",
    "Memory Management",
    "File Systems",
    "CPU Scheduling",
    "I/O Management",
    "Deadlock",
    "Process Synchronization"
  ],
  "flashcards": [
    {
      "id": "fc-1",
      "topic": "Operating System Definition",
      "question": "What is the primary role of an Operating System?",
      "answer": "To act as an intermediary between computer hardware and the user, managing resources and providing a user interface."
    },
    {
      "id": "fc-2",
      "topic": "Process Management",
      "question": "What is a 'process' in an operating system?",
      "answer": "An instance of a program currently in execution."
    },
    {
      "id": "fc-3",
      "topic": "CPU Scheduling",
      "question": "Name four common CPU scheduling algorithms.",
      "answer": "FCFS, SJF, Priority Scheduling, and Round Robin (RR)."
    },
    {
      "id": "fc-4",
      "topic": "Memory Management",
      "question": "What are common techniques used for efficient memory management?",
      "answer": "Paging, Segmentation, Virtual Memory, Demand Paging, and Memory Protection."
    },
    {
      "id": "fc-5",
      "topic": "File Systems",
      "question": "What is the purpose of a file system?",
      "answer": "To organize data into files and directories for efficient storage, retrieval, modification, and deletion."
    },
    {
      "id": "fc-6",
      "topic": "I/O Management",
      "question": "How do hardware devices communicate with the operating system?",
      "answer": "Through device drivers, which act as translators."
    },
    {
      "id": "fc-7",
      "topic": "Deadlock",
      "question": "What are the four necessary conditions for a deadlock to occur?",
      "answer": "Mutual Exclusion, Hold and Wait, No Preemption, and Circular Wait."
    },
    {
      "id": "fc-8",
      "topic": "Deadlock Handling",
      "question": "What are the four methods for handling deadlocks?",
      "answer": "Prevention, avoidance (e.g., Banker's Algorithm), detection, and recovery."
    },
    {
      "id": "fc-9",
      "topic": "Process Synchronization",
      "question": "What is a 'Critical Section' problem?",
      "answer": "When multiple processes attempt to modify shared data simultaneously, requiring synchronization."
    },
    {
      "id": "fc-10",
      "topic": "Synchronization Mechanisms",
      "question": "Name three mechanisms used for process synchronization.",
      "answer": "Mutex Locks, Semaphores, and Monitors."
    }
  ]
}
